    wire a = c;
    wire b = d;
    wire [3:0] mux_in_stage1 [0:7];
    wire [3:0] mux_in_stage2 [0:3];
    wire [3:0] mux_in_stage3;
    assign mux_in_stage1[0] = 1'b0;
    assign mux_in_stage1[1] = 1'b0;
    assign mux_in_stage1[2] = 1'b0;
    assign mux_in_stage1[3] = 1'b1;
    assign mux_in_stage1[4] = 1'b0;
    assign mux_in_stage1[5] = 1'b0;
    assign mux_in_stage1[6] = 1'b1;
    assign mux_in_stage1[7] = 1'b1;
    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : stage1_loop
